//! Generates the compiled form of the users' guide's tested example.
//!
//! `docs/users-guide.md` is the source of truth: this script extracts the
//! fence marked `<!-- tested-example: session-refresh -->`, wraps it in a
//! module, and writes that module under `OUT_DIR`. The integration test
//! `tests/users_guide_session_refresh.rs` and the behavioural scenarios in
//! `tests/session_append_bdd.rs` include the generated file, so the text the
//! tests compile is the text the guide publishes. A missing marker, a
//! duplicate identifier, a detached marker or an unterminated fence fails the
//! build here, with the offending line number.

use std::{
    error::Error,
    io::{self, Write},
};

use camino::{Utf8Path, Utf8PathBuf};
use cap_std::fs_utf8::Dir;
use mockable::{DefaultEnv, Env};

#[path = "build_support/users_guide_examples.rs"]
mod users_guide_examples;

use users_guide_examples::extract_example;

/// Identifier of the example the tests execute.
const EXAMPLE_ID: &str = "session-refresh";
/// Repository-relative path of the published guide.
const GUIDE: &str = "docs/users-guide.md";
/// File name written under `OUT_DIR`.
const GENERATED_FILE: &str = "users_guide_session_refresh.rs";

/// Opening of the generated module, up to the example body.
///
/// The two expectations cover the published text itself, which is not edited
/// here: it computes an absolute scalar distance, and its `main` asserts the
/// documented outcome before returning `Ok(())`. A guide example that quietly
/// dropped those assertions would be a weaker contract, so the lints are
/// expected rather than the example rewritten.
const MODULE_PREFIX: &str = concat!(
    "// The users' guide's session-refresh example.\n",
    "//\n",
    "// Generated by chutoro-core/build.rs from the fence marked\n",
    "// `tested-example: session-refresh` in docs/users-guide.md. Edit the\n",
    "// guide, not this file.\n",
    "#[expect(\n",
    "    clippy::float_arithmetic,\n",
    "    reason = \"the published example computes an absolute scalar distance\"\n",
    ")]\n",
    "#[expect(\n",
    "    clippy::panic_in_result_fn,\n",
    "    reason = \"the published example asserts its documented outcome\"\n",
    ")]\n",
    "mod published_example {\n",
    "    //! The users' guide's session-refresh example.\n",
    "    //!\n",
    "    //! Generated from the fence marked `tested-example: session-refresh`\n",
    "    //! in `docs/users-guide.md`; edit the guide, not this module.\n",
    "\n",
);

/// Closing of the generated module: the entry point the tests call.
const MODULE_SUFFIX: &str = concat!(
    "\n    /// Runs the published example and returns its outcome.\n",
    "    ///\n",
    "    /// # Errors\n",
    "    ///\n",
    "    /// Returns the example's own error when a session operation fails.\n",
    "    pub(super) fn run() -> Result<(), chutoro_core::ChutoroError> {\n",
    "        main()\n",
    "    }\n",
    "}\n",
);

fn main() -> Result<(), Box<dyn Error>> {
    emit_directive("cargo:rerun-if-changed=build.rs")?;
    emit_directive("cargo:rerun-if-changed=build_support/users_guide_examples.rs")?;
    emit_directive("cargo:rerun-if-changed=../docs/users-guide.md")?;

    let manifest = Utf8Path::new(env!("CARGO_MANIFEST_DIR"));
    let repository = Dir::open_ambient_dir(manifest.join(".."), cap_std::ambient_authority())?;
    let guide = repository.read_to_string(GUIDE)?;
    let body = extract_example(&guide, EXAMPLE_ID)?;
    let generated = format!("{MODULE_PREFIX}{body}{MODULE_SUFFIX}");

    let out_dir = DefaultEnv
        .os_string("OUT_DIR")
        .map(std::path::PathBuf::from)
        .and_then(|path| Utf8PathBuf::from_path_buf(path).ok())
        .ok_or_else(|| io::Error::other("OUT_DIR must be a UTF-8 path"))?;
    let out = Dir::open_ambient_dir(&out_dir, cap_std::ambient_authority())?;
    out.write(GENERATED_FILE, generated)?;
    Ok(())
}

/// Writes one build-script directive for Cargo to consume.
fn emit_directive(directive: &str) -> io::Result<()> {
    writeln!(io::stdout().lock(), "{directive}")
}
